{"expression":"result != 0 || r->buf[(r->tail + 3) % 4] == v","domain":["r->count <= 4","r->head < 4","r->tail < 4"],"referenced_params":["r","v"],"rationale":"A successful push stores v in the slot just before the new tail, so the pushed value is the most recent write."},
{"expression":"result != 0 || r->count >= 1","domain":["r->count <= 4"],"referenced_params":["r"],"rationale":"After a successful push the buffer cannot be empty."},
{"expression":"r->count <= 4","domain":["r->count <= 4"],"referenced_params":["r"],"rationale":"Capacity invariant: a push never overfills the buffer, whether it succeeds or is rejected."},
{"expression":"r->tail < 4","domain":["r->count <= 4","r->tail < 4"],"referenced_params":["r"],"rationale":"The tail index stays inside the array after the call, so the wrap-around is correct."},
{"expression":"r->head < 4","domain":["r->count <= 4","r->head < 4"],"referenced_params":["r"],"rationale":"The head index stays inside the array after the call, whether or not the push succeeded."},
{"expression":"result == 0 || result == -1","domain":["r->count <= 4"],"referenced_params":["r"],"rationale":"The return value is a status code: 0 on success, -1 when the buffer is full."}
]}
